SELECT COUNT(*) AS total_contacts, COUNT(DISTINCT employee_id) AS unique_employees, SUM(photo_source='PEXELS_STOCK_DEMO') AS new_source_count FROM employee_contacts;
SELECT c.employee_id, e.employee_name, c.photo_url, c.photo_status FROM employee_contacts c JOIN employees e ON e.employee_id=c.employee_id ORDER BY c.employee_id LIMIT 10;
